package android.content; public class Context { public static int permission=0; public Context getApplicationContext(){return this;} public android.content.pm.PackageManager getPackageManager(){return new android.content.pm.PackageManager();} public android.content.pm.ApplicationInfo getApplicationInfo(){return new android.content.pm.ApplicationInfo();} public String getPackageName(){return "com.android.shell";} public String getOpPackageName(){return getPackageName();} public AttributionSource getAttributionSource(){return new AttributionSource();} public android.content.res.AssetManager getAssets(){return new android.content.res.AssetManager();} public ContentResolver getContentResolver(){return new ContentResolver();} public int checkSelfPermission(String p){return permission;} public <T> T getSystemService(Class<T> c){if(c==android.app.AppOpsManager.class)return c.cast(new android.app.AppOpsManager()); return c.cast(android.app.appfunctions.AppFunctionManager.INSTANCE);} }
